local function runModule(file)
    if moduleInMaintenance(file) then
        return false
    end
    local source = EMBEDDED_MODULES[file]
    local ok, err = pcall(function()
        if type(source) ~= "string" or #source == 0 then
            error("module not embedded: " .. tostring(file))
        end
        loadstring(source, "@" .. file)()
    end)
    if not ok then
        warn("[Young0x Hub] " .. file .. ": " .. tostring(err))
    end
    return ok
end

