        }, visual)
        corner(dot, 99)

        local state = {
            module = module,
            button = button,
            visual = visual,
            visualScale = visualScale,
            icon = icon,
            name = nameLabel,
            dot = dot,
            hovered = false,
            clickSerial = 0,
            offsetX = 0,
            offsetY = 0,
        }
        moduleStates[index] = state

        track(button.MouseEnter:Connect(function()
            if not closing then
                setModuleHover(state, true)
            end
        end))

        track(button.MouseLeave:Connect(function()
            setModuleHover(state, false)
        end))

        track(button.Activated:Connect(function()
            if closing or launching or transitioning then
                return
            end
            pulseModule(state)
            if maintenance then
                showLoaderStatus("Update in progress", COLOR.Subtext, 2.2)
                return
            end

            if module.file == "000.lua" then
                local existing = playerGui:FindFirstChild("FG100Hub")
                    or playerGui:FindFirstChild("Young0xFG100Hub")
                if existing then
                    setFG100AccessVisual(true)
                    closeOnly()
                    return
                end
                launching = true
                button.Active = false
                showLoaderStatus("Loading FG100...", COLOR.Text, 45)
                task.spawn(function()
                    local launched = runModule(module.file)
                    launching = false
                    if button.Parent then
                        button.Active = true
                    end
                    if launched and gui.Parent then
                        setFG100AccessVisual(true)
                        destroyLoader()
                    end
                end)
                return
            end

            launching = true
            task.delay(0.12, function()
                if gui.Parent then
                    closeAndRun(module.file)
                end
            end)
        end))
    end

    setFG100AccessVisual = function(hasAccess)
        for _, state in ipairs(moduleStates) do
            if state.module.file == "000.lua" then
                local color = hasAccess and COLOR.Green or COLOR.Error
                state.module.accent = color
                playTween(state.dot, 0.24, { BackgroundColor3 = color }, Enum.EasingStyle.Quint)
                break
            end
        end
    end

    local function exitAnimation(onComplete)
        if closing then
            return
        end
        closing = true
        dragging = false
        local exitTween = playTween(stage, 0.2, {
            GroupTransparency = 1,
            Position = UDim2.new(stage.Position.X.Scale, stage.Position.X.Offset, stage.Position.Y.Scale, stage.Position.Y.Offset + 18),
        }, Enum.EasingStyle.Quart, Enum.EasingDirection.In)
        playTween(scale, 0.2, { Scale = scale.Scale * 0.93 }, Enum.EasingStyle.Quart, Enum.EasingDirection.In)
        track(exitTween.Completed:Connect(function()
            destroyLoader()
            if onComplete then
                onComplete()
            end
        end))
    end

    closeOnly = function()
        if launching then
            return
        end
        exitAnimation()
    end

    closeAndRun = function(file)
        exitAnimation(function()
            runModule(file)
        end)
    end

    local function showShop()
        if closing or transitioning or launching then
            return
        end
        transitioning = true
        statusSerial += 1
        shopStatus.Text = ""
        shopStatus.TextTransparency = 1
        playTween(loaderPage, 0.16, { GroupTransparency = 1 }, Enum.EasingStyle.Quart)
        playTween(stage, 0.38, { Size = UDim2.fromOffset(SHOP_WIDTH, SHOP_HEIGHT) }, Enum.EasingStyle.Quint)
        task.delay(0.16, function()
            if not stage.Parent then return end
            loaderPage.Visible = false
            shopPage.Visible = true
            shopPage.GroupTransparency = 1
            playTween(shopPage, 0.24, { GroupTransparency = 0 }, Enum.EasingStyle.Quint)
            currentWidth = SHOP_WIDTH
            currentHeight = SHOP_HEIGHT
            if updateScale then
                updateScale(true)
            end
            task.delay(0.24, function()
                transitioning = false
            end)
        end)
    end

